import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static class IntList {
        int[] data = new int[2];
        int size = 0;

        void add(int value) {
            if (size == data.length) data = Arrays.copyOf(data, size << 1);
            data[size++] = value;
        }

        int lowerBound(int value) {
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (data[mid] < value) lo = mid + 1;
                else hi = mid;
            }
            return lo;
        }

        int upperBound(int value) {
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (data[mid] <= value) lo = mid + 1;
                else hi = mid;
            }
            return lo;
        }
    }

    static class LongMap {
        private final long[] keys;
        private final IntList[] values;
        private final int mask;

        LongMap(int expectedSize) {
            int capacity = 1;
            while (capacity < expectedSize * 2) capacity <<= 1;
            keys = new long[capacity];
            values = new IntList[capacity];
            mask = capacity - 1;
        }

        private int hash(long key) {
            key ^= key >>> 33;
            key *= 0xff51afd7ed558ccdL;
            key ^= key >>> 33;
            key *= 0xc4ceb9fe1a85ec53L;
            key ^= key >>> 33;
            return (int) key & mask;
        }

        void add(long key, int index) {
            int pos = hash(key);
            while (values[pos] != null && keys[pos] != key) pos = (pos + 1) & mask;
            if (values[pos] == null) {
                keys[pos] = key;
                values[pos] = new IntList();
            }
            values[pos].add(index);
        }

        IntList get(long key) {
            int pos = hash(key);
            while (values[pos] != null) {
                if (keys[pos] == key) return values[pos];
                pos = (pos + 1) & mask;
            }
            return null;
        }
    }

    static int[] prevParent, nextParent;

    static int findPrev(int x) {
        int root = x;
        while (prevParent[root] != root) root = prevParent[root];
        while (prevParent[x] != x) {
            int next = prevParent[x];
            prevParent[x] = root;
            x = next;
        }
        return root;
    }

    static int findNext(int x) {
        int root = x;
        while (nextParent[root] != root) root = nextParent[root];
        while (nextParent[x] != x) {
            int next = nextParent[x];
            nextParent[x] = root;
            x = next;
        }
        return root;
    }

    static long count(LongMap map, long key, int lo, int hi) {
        if (lo > hi) return 0;
        IntList list = map.get(key);
        if (list == null) return 0;
        return list.upperBound(hi) - list.lowerBound(lo);
    }

    static long countGreater(int i, int lo, int hi, long k, long[] x, long[] y,
                             LongMap xPositions, LongMap yPositions) {
        long upperX = Math.min((long) hi, (long) i + k);
        long upperY = Math.min((long) hi, (long) i + k - 1);
        return count(xPositions, x[i] + k, lo, (int) upperX)
             + count(yPositions, y[i] + k, lo, (int) upperY);
    }

    static long countLess(int i, int lo, int hi, long k, long[] x, long[] y,
                          LongMap xPositions, LongMap yPositions) {
        long lowerX = Math.max((long) lo, (long) i - k);
        long lowerY = Math.max((long) lo, (long) i - k + 1);
        return count(xPositions, x[i] - k, (int) lowerX, hi)
             + count(yPositions, y[i] - k, (int) lowerY, hi);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int q = fs.nextInt();
        long k = fs.nextInt();

        long[] x = new long[n + 1];
        long[] y = new long[n + 1];
        LongMap xPositions = new LongMap(n);
        LongMap yPositions = new LongMap(n);

        for (int i = 1; i <= n; i++) {
            long height = fs.nextInt();
            x[i] = i + height;
            y[i] = i - height;
            xPositions.add(x[i], i);
            yPositions.add(y[i], i);
        }

        long total = 0;
        for (int j = 1; j <= n; j++) {
            total += countLess(j, 1, j - 1, k, x, y, xPositions, yPositions);
        }

        prevParent = new int[n + 1];
        nextParent = new int[n + 2];
        for (int i = 0; i <= n; i++) prevParent[i] = i;
        for (int i = 0; i <= n + 1; i++) nextParent[i] = i;

        StringBuilder out = new StringBuilder();
        out.append(total).append('\n');

        for (int t = 0; t < q; t++) {
            int d = fs.nextInt();
            int leftBoundary = findPrev(d - 1) + 1;
            int rightBoundary = findNext(d + 1) - 1;

            long removed = countLess(d, leftBoundary, d - 1, k, x, y, xPositions, yPositions)
                         + countGreater(d, d + 1, rightBoundary, k, x, y, xPositions, yPositions);

            int leftSize = d - leftBoundary;
            int rightSize = rightBoundary - d;

            if (leftSize <= rightSize) {
                for (int i = leftBoundary; i < d; i++) {
                    removed += countGreater(i, d + 1, rightBoundary, k, x, y,
                                            xPositions, yPositions);
                }
            } else {
                for (int j = d + 1; j <= rightBoundary; j++) {
                    removed += countLess(j, leftBoundary, d - 1, k, x, y,
                                         xPositions, yPositions);
                }
            }

            total -= removed;
            out.append(total).append('\n');

            prevParent[d] = findPrev(d - 1);
            nextParent[d] = findNext(d + 1);
        }

        System.out.print(out);
    }
